// Caminho: gestores/servidor/Arcoll.WinUI3/Services/BackupCenter/BackupExecutor.cs
using System.Diagnostics;
using System.Security.Cryptography;
using System.Text.Json;
namespace Arcoll.WinUI3.Services.BackupCenter;
/// <summary>Backup por arquivo; nunca altera fontes. Pontos novos não propagam exclusões locais.</summary>
public sealed class BackupExecutor(IBackupRemote remote,string workRoot,string restoreRoot)
{
 private DateTime _reported=DateTime.MinValue;
 private async Task Tick(BackupOperation op,BackupSummary summary,CancellationToken ct,bool force=false){if(force||DateTime.UtcNow-_reported>=TimeSpan.FromSeconds(8)){await remote.ProgressAsync(op,summary,ct);_reported=DateTime.UtcNow;}}
 public async Task RunAsync(BackupOperation op,CancellationToken ct){var summary=new BackupSummary();try{BackupSafety.NoLinks(workRoot);Directory.CreateDirectory(workRoot);if(op.Kind=="backup")await BackupAsync(op,summary,ct);else if(op.Kind is "restore" or "verify")await RecoverAsync(op,summary,ct);else throw new IOException("Tipo de operação não suportado.");}
  catch(OperationCanceledException)when(ct.IsCancellationRequested){throw;}
  catch(BackupRemoteException ex)when(ex.Status==409){/* O servidor é a autoridade sobre cancelamento/lease. */}
  catch(Exception ex){summary.Error(summary.Current,ex.Message);summary.Message="Operação interrompida: "+ex.Message;try{using var fail=new CancellationTokenSource(TimeSpan.FromSeconds(20));await remote.FailAsync(op,summary,fail.Token);}catch(Exception){}throw;}
 }
 private async Task BackupAsync(BackupOperation op,BackupSummary summary,CancellationToken ct){var plan=op.Plan;var settings=plan.Settings;var batch=new List<BackupFile>();var manifest=new List<BackupFile>();BackupRepository? repository=plan.Target=="local"?new(plan):null;var staging=BackupSafety.SafeChild(workRoot,"staging",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(staging);summary.Phase="scanning";summary.Message="Examinando arquivos de dados. Sem VSS/consistência de aplicações.";await Tick(op,summary,ct,true);
  try{for(var index=0;index<settings.Folders.Length;index++){ct.ThrowIfCancellationRequested();var root=Path.GetFullPath(Environment.ExpandEnvironmentVariables(settings.Folders[index]));try{BackupSafety.DataRoot(root);if(!Directory.Exists(root))throw new DirectoryNotFoundException("Pasta de origem indisponível.");
    foreach(var path in BackupSafety.Enumerate(root,workRoot,settings.Exclusions,error=>summary.Error(root,error),ct)){
     if(manifest.Count>=20000){summary.Error(root,"Limite de 20.000 arquivos por ponto atingido. Divida as origens em planos.");break;}var relative=Path.GetRelativePath(root,path).Replace('\\','/');summary.Current=relative;string? spool=null;
     try{BackupSafety.Relative(relative);if(BackupSafety.LiveDatabase(path))throw new IOException("Banco/disco virtual ativo exige exportação nativa ou solução VSS; formato não incluído neste backup.");BackupSafety.NoLinks(path);var info=new FileInfo(path);var maximum=Math.Min((long)settings.MaxFileMb*1048576,plan.Target=="cloud"?op.MaxFileBytes:long.MaxValue);if(info.Length>maximum)throw new IOException("Arquivo acima do limite do plano/destino.");var drive=Path.GetPathRoot(workRoot);if(drive is not null&&new DriveInfo(drive).AvailableFreeSpace<info.Length+67108864)throw new IOException("Área temporária sem espaço para cópia estável do arquivo.");spool=BackupSafety.SafeChild(staging,Guid.NewGuid().ToString("N")+".spool");
      var snapshot=await SpoolAsync(path,spool,op,summary,ct);var file=new BackupFile(index,relative,snapshot.Sha,snapshot.Size,snapshot.Mtime);summary.Phase=plan.Target=="cloud"?"uploading":"copying";
      bool changed;if(repository is not null)changed=await repository.PutAsync(spool,file.Digest,async size=>{summary.Bytes+=size;await Tick(op,summary,ct);},ct);else changed=await UploadAsync(op,spool,snapshot,summary,ct);
      if(!changed)summary.Unchanged++;manifest.Add(file);batch.Add(file);summary.Files++;summary.LogicalBytes+=file.Size;
      if(batch.Count>=100){await remote.FilesAsync(op,batch,ct);batch.Clear();}await Tick(op,summary,ct);
     }catch(BackupRemoteException ex)when(ex.Status is 401 or 403 or 409 or 429 or 502 or 503){throw;}
     catch(Exception error)when(error is not OperationCanceledException){summary.Error(relative,error.Message);}
     finally{if(spool is not null&&File.Exists(spool))File.Delete(spool);}
    }
   }catch(BackupRemoteException){throw;}catch(Exception error)when(error is not OperationCanceledException){summary.Error(root,error.Message);}await Tick(op,summary,ct,true);
  }
  if(batch.Count>0)await remote.FilesAsync(op,batch,ct);summary.Phase="committing";summary.Message=summary.Errors>0?"Backup parcial: há itens não protegidos. Revise as falhas.":"Ponto de recuperação criado. Agende/teste a restauração para comprovar recuperabilidade.";await Tick(op,summary,ct,true);
  // Manifesto independente local antes de confirmar o catálogo remoto.
  if(repository is not null){var local=JsonSerializer.Serialize(new BackupManifest("tidigital.backup.v1",manifest),BackupJson.Options);repository.SavePoint(op.Id,local,BackupSafety.HashText(local));}
  var result=await remote.FinishAsync(op,summary,ct);if(BackupSafety.HashText(result.Canonical)!=result.Digest)throw new IOException("Catálogo devolveu manifesto inconsistente.");repository?.SavePoint(op.Id,result.Canonical,result.Digest);
  }finally{if(Directory.Exists(staging))Directory.Delete(staging,true);}
 }
 private sealed record SpoolResult(string Sha,string Md5,long Size,long Mtime);
 private async Task<SpoolResult> SpoolAsync(string source,string target,BackupOperation op,BackupSummary summary,CancellationToken ct){var info=new FileInfo(source);var before=(info.Length,info.LastWriteTimeUtc.Ticks);using var sha=IncrementalHash.CreateHash(HashAlgorithmName.SHA256);using var md5=IncrementalHash.CreateHash(HashAlgorithmName.MD5);long total=0;
  await using(var input=new FileStream(source,FileMode.Open,FileAccess.Read,FileShare.Read,1048576,true))await using(var output=new FileStream(target,FileMode.CreateNew,FileAccess.Write,FileShare.None,1048576,true)){BackupSafety.NoLinks(source);var buffer=new byte[1048576];int size;while((size=await input.ReadAsync(buffer,ct))>0){sha.AppendData(buffer,0,size);md5.AppendData(buffer,0,size);await output.WriteAsync(buffer.AsMemory(0,size),ct);total+=size;summary.Phase="hashing";await Tick(op,summary,ct);}await output.FlushAsync(ct);output.Flush(true);info.Refresh();if(total!=before.Length||info.Length!=before.Length||info.LastWriteTimeUtc.Ticks!=before.Ticks)throw new IOException("Arquivo mudou durante a captura; não foi incluído no ponto.");}
  return new(Convert.ToHexString(sha.GetHashAndReset()).ToLowerInvariant(),Convert.ToHexString(md5.GetHashAndReset()).ToLowerInvariant(),total,new DateTimeOffset(new DateTime(before.Ticks,DateTimeKind.Utc)).ToUnixTimeSeconds());
 }
 private async Task<bool> UploadAsync(BackupOperation op,string spool,SpoolResult file,BackupSummary summary,CancellationToken ct){var reply=await remote.BeginAsync(op,file.Sha,file.Md5,file.Size,ct);if(reply.Done)return false;if(reply.Chunk<1||reply.Chunk>5242880||string.IsNullOrEmpty(reply.UploadId))throw new IOException("Sessão de envio inválida.");var upload=reply.UploadId;var chunk=reply.Chunk;var offset=reply.NextOffset;var stalls=0;
  await using var input=new FileStream(spool,FileMode.Open,FileAccess.Read,FileShare.Read,chunk,true);while(!reply.Done){ct.ThrowIfCancellationRequested();if(offset<0||offset>=file.Size)throw new IOException("Offset de envio inválido.");input.Position=offset;var data=new byte[(int)Math.Min(chunk,file.Size-offset)];var read=0;while(read<data.Length){var count=await input.ReadAsync(data.AsMemory(read),ct);if(count==0)throw new IOException("Captura temporária incompleta.");read+=count;}var watch=Stopwatch.StartNew();reply=await remote.ChunkAsync(op,file.Sha,file.Md5,upload,offset,data,ct);if(reply.NextOffset<0||reply.NextOffset>file.Size)throw new IOException("Offset confirmado fora do arquivo.");if(reply.NextOffset==offset&&++stalls>3)throw new IOException("Destino não avançou a transferência.");if(reply.NextOffset!=offset)stalls=0;summary.Bytes+=Math.Max(0,reply.NextOffset-offset);offset=reply.NextOffset;
   if(op.Plan.Settings.BandwidthKbps>0){var expected=(double)data.Length/(op.Plan.Settings.BandwidthKbps*1024d);while(watch.Elapsed.TotalSeconds<expected){await Tick(op,summary,ct);await Task.Delay(TimeSpan.FromSeconds(Math.Min(1,expected-watch.Elapsed.TotalSeconds)),ct);}}
   summary.SpeedBps=(long)(data.Length/Math.Max(.001,watch.Elapsed.TotalSeconds));await Tick(op,summary,ct);
  }if(offset!=file.Size)throw new IOException("Destino não confirmou o tamanho completo.");return true;
 }
 private async Task RecoverAsync(BackupOperation op,BackupSummary summary,CancellationToken ct){var reply=await remote.ManifestAsync(op,ct);if(BackupSafety.HashText(reply.Canonical)!=reply.Digest)throw new IOException("Manifesto alterado/incompleto.");var manifest=JsonSerializer.Deserialize<BackupManifest>(reply.Canonical,BackupJson.Options)??throw new IOException("Manifesto inválido.");if(manifest.Schema!="tidigital.backup.v1"||manifest.Files.Count>20000)throw new IOException("Versão/limite de manifesto não suportado.");var selected=reply.Selection.Length>0?manifest.Files.Where(x=>reply.Selection.Contains(x.PathHash)).ToArray():manifest.Files.ToArray();if(reply.Selection.Any(id=>!manifest.Files.Any(x=>x.PathHash==id)))throw new IOException("Seleção não pertence ao manifesto.");
  BackupRepository? repository=reply.Plan.Target=="local"?new(reply.Plan):null;string? destination=null;if(op.Kind=="restore"){BackupSafety.NoLinks(restoreRoot);Directory.CreateDirectory(restoreRoot);destination=BackupSafety.SafeChild(restoreRoot,op.Id);if(Directory.Exists(destination))throw new IOException("Pasta de restauração já existe; nada será sobrescrito.");Directory.CreateDirectory(destination);summary.Destination=destination;}summary.Phase=op.Kind=="verify"?"verifying":"restoring";await Tick(op,summary,ct,true);
  foreach(var file in selected){ct.ThrowIfCancellationRequested();summary.Current=file.Relative;string? temp=null;try{
    BackupSafety.Relative(file.Relative);if(file.Folder<0||file.Folder>=reply.Plan.Settings.Folders.Length||file.Size<0||!System.Text.RegularExpressions.Regex.IsMatch(file.Digest,"^[a-f0-9]{64}$"))throw new IOException("Metadados do manifesto inválidos.");string? target=null;if(destination is not null){target=BackupSafety.SafeChild(destination,"Origem"+(file.Folder+1),file.Relative.Replace('/',Path.DirectorySeparatorChar));Directory.CreateDirectory(Path.GetDirectoryName(target)!);BackupSafety.NoLinks(target);if(File.Exists(target))throw new IOException("Conflito de nome; arquivo existente preservado.");temp=target+"."+Guid.NewGuid().ToString("N")+".partial";}
    await using var source=repository is null?await remote.DownloadAsync(op,file,ct):repository.Open(file);await using var output=temp is null?Stream.Null:new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None,1048576,true);using var sha=IncrementalHash.CreateHash(HashAlgorithmName.SHA256);var buffer=new byte[1048576];long total=0;int size;
    while(true){using var timeout=CancellationTokenSource.CreateLinkedTokenSource(ct);timeout.CancelAfter(TimeSpan.FromSeconds(60));size=await source.ReadAsync(buffer,timeout.Token);if(size==0)break;total+=size;if(total>file.Size)throw new IOException("Objeto excede o tamanho do manifesto.");sha.AppendData(buffer,0,size);await output.WriteAsync(buffer.AsMemory(0,size),ct);summary.Bytes+=size;await Tick(op,summary,ct);}
    var digest=Convert.ToHexString(sha.GetHashAndReset()).ToLowerInvariant();if(total!=file.Size||digest!=file.Digest)throw new IOException("Checksum SHA-256/tamanho não confere; arquivo não restaurado.");await output.FlushAsync(ct);if(output is FileStream disk)disk.Flush(true);output.Dispose();
    if(temp is not null&&target is not null){BackupSafety.NoLinks(target);File.Move(temp,target,false);temp=null;if(file.Mtime>0&&file.Mtime<DateTimeOffset.UtcNow.AddDays(1).ToUnixTimeSeconds())File.SetLastWriteTimeUtc(target,DateTimeOffset.FromUnixTimeSeconds(file.Mtime).UtcDateTime);}summary.Files++;summary.LogicalBytes+=file.Size;
   }catch(BackupRemoteException error)when(error.Status is 401 or 403 or 409){throw;}catch(Exception error)when(error is not OperationCanceledException||!ct.IsCancellationRequested){summary.Error(file.Relative,error.Message);}finally{if(temp is not null&&File.Exists(temp))File.Delete(temp);}await Tick(op,summary,ct);
  }
  summary.Message=summary.Errors>0?"Operação parcial/falhou: revise arquivos não recuperados/verificados.":op.Kind=="verify"?"Leitura completa e checksum SHA-256 conferidos para a seleção.":"Arquivos restaurados em pasta nova, sem sobrescrever a origem.";await remote.FinishOperationAsync(op,summary,ct);
 }
}
